css:
.action-banner a[href*="frappe.utils.print_format.download_pdf"] {
    display: none !important;
}
        
.print-format td, .print-format th {
    padding: 0px !important;
}

/* General styling for tables */
table {
    border-collapse: collapse;
    table-layout: fixed; /* Ensures consistent column widths */
    width: 50%;  /* Default width for larger screens */
    font-size: 8pt;
    text-align: center;
    margin-left: 20px;
}

/* Adjust table width for smaller screens (below 768px) */
@media (max-width: 768px) {
    table {
        width: 100%;  /* Full width for smaller screens */
        font-size: 6pt; /* Optionally reduce font size */
        margin-left: 0; /* Remove left margin for better fitting */
    }
}

/* Adjust table width for printing (PDF output) */
@media print {
    table {
        width: 50%;  /* Use 50% width when printing in FrappeHR or generating PDF */
        font-size: 8pt; /* Maintain readable font size during print */
        margin-left: 0; /* Remove margin for print */
    }
    
    @page{
        size:A4;
    }
}


img#qr {
  display: block;
  width: 50px !important;
  height: 50px;
}

html:
    {% set employees = frappe.get_all(
        "Employee",
        filters={"employee": doc.employee},
        fields=["employee", "employee_name", "custom_name_extension", "custom_category"]) 
    %}
    {% set month_mapping = {
        "January": "01", "February": "02", "March": "03", "April": "04",
        "May": "05", "June": "06", "July": "07", "August": "08",
        "September": "09", "October": "10", "November": "11", "December": "12"
    } %}
    
    {% if doc.month %}
        {% set month = month_mapping[doc.month] %}
    {% endif %} 
    
    {% if doc.cut_off == '16-31' or doc.cut_off == '1-31'  %}
        {% set month_days = {
            "January": 31, "February": 28, "March": 31, "April": 30,
            "May": 31, "June": 30, "July": 31, "August": 31,
            "September": 30, "October": 31, "November": 30, "December": 31
        } %}
        
        {% set selected_month = doc.month %}
        {% set selected_year = doc.year|int %}
        
        {# Adjust for Leap Year in February #}
        {% if selected_month == "February" and (selected_year is divisibleby 4 and (selected_year is not divisibleby 100 or selected_year is divisibleby 400)) %}
            {% set days_in_month = 29 %}
        {% else %}
            {% set days_in_month = month_days[selected_month] %}
        {% endif %}
    {% else %}
        {% set days_in_month = 15 %}
    {% endif %}
    
    {% if doc.cut_off == '16-31' %}
        {% set start_day = 16 %}
    {% else %}
        {% set start_day = 1 %}
    {% endif %}
    
    {% set qr_data = frappe.utils.get_url("/printview?doctype=" + ("Daily%20Time%20Record&name=" + doc.name + "&format=DTR") | urlencode) %}

    {% set date_from = doc.year ~ "-" ~ month ~ "-" ~ ("%02d"|format(start_day|int)) %}
    {% set date_to = doc.year ~ "-" ~ month ~ "-" ~ ("%02d"|format(days_in_month|int)) %}
    {% set holidays = frappe.get_all( "Holiday", fields=["parent", "holiday_date", "description", "weekly_off"], filters={ "holiday_date": ["between", [date_from, date_to]] }, order_by="holiday_date" ) %}
    {% set holiday_days = [] %} 
    {% for h in holidays %} 
        {% set _ = holiday_days.append(h.holiday_date.strftime("%d")|int) %} 
    {% endfor %}

    <table>
        <tr>
            <td colspan="5" style="text-align: left; font-style: italic;">Civil Service FORM No. 48</td>
            <td colspan="2">
                <img id="qr" src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&data={{ qr_data }}" style="float: right;">
            </td>
        </tr>
        <tr>
            <td colspan="7" style="font-weight: bold; font-size: 14pt; line-height: 3;">DAILY TIME RECORD</td>
        </tr>
        <tr>
            <td colspan="7" style="font-size: 12pt; border-bottom: 1pt solid black;">{{employees[0].employee_name|upper + ' ' + employees[0].custom_name_extension|upper if employees[0].custom_name_extension else employees[0].employee_name|upper}}</td>
        </tr>
        <tr>
            <td colspan="7" style="font-weight: bold; line-height: 2;">NAME</td>
        </tr>
        <tr>
            <td colspan="7" style="border-bottom: 1pt solid black;">{{ doc.month }} {{ start_day }}-{{ days_in_month }}, {{ doc.year }}</td>
        </tr>
        <tr>
            <td colspan="7" style="font-weight: bold; line-height: 2;">MONTH</td>
        </tr>
        <tr>
            <td colspan="3" style="text-align: left;">Official hours for arrival</td>
            <td colspan="3" style="text-align: left;">Regular days</td>
        </tr>
        <tr>
            <td colspan="3" style="text-align: left;">and departure</td>
            <td colspan="3" style="text-align: left;">Saturdays</td>
        </tr>
    </table>
    
    <table border="1" style="margin-bottom: 20px;">
        <tr style="border-top: double;">
            <td></td>
            <td colspan="2">A.M.</td>
            <td colspan="2">P.M.</td>
            <td colspan="2">UNDERTIME</td>
        </tr>
        <tr>
            <td>DAY</td>
            <td>Arrival</td>
            <td>Departure</td>
            <td>Arrival</td>
            <td>Departure</td>
            <td>Hours</td>
            <td>Minutes</td>
        </tr>
        {% for d in range(1,32) %}
            {% set date = doc.year ~ "-" ~ month ~ "-" ~ ("%02d"|format(d)) %}
            <!-- Date of implementation for No Break Out and Break In -->
            {% set target_date = '2025-04-14' %} 

            {% if d >= start_day and days_in_month >= d %}
                {% 
                    set checkins = frappe.get_all(
                    "Employee Checkin",
                    filters={
                        "employee": employees[0].employee,
                        "log_type": "IN",
                        "custom_is_break": 0,
                        "time": ["between", [date + " 00:00:00", date + " 23:59:59"]]
                    },
                    fields=["time","custom_remarks"],
                    order_by="time ASC", 
                    limit=1 
                )
                %}
                {% 
                    set checkouts = frappe.get_all(
                    "Employee Checkin",
                    filters={
                        "employee": employees[0].employee,
                        "log_type": "OUT",
                        "custom_is_break": 0,
                        "time": ["between", [date + " 00:00:00", date + " 23:59:59"]]
                    },
                    fields=["time","custom_remarks"],
                    order_by="time DESC", 
                    limit=1 
                )
                %}      
                {% 
                    set breakouts = frappe.get_all(
                        "Employee Checkin",
                        filters={
                            "employee": employees[0].employee,
                            "log_type": "OUT",
                            "custom_is_break": 1,
                            "time": ["between", [date + " 00:00:00", date + " 23:59:59"]]
                        },
                        fields=["time"],
                        order_by="time DESC", 
                        limit=1 
                    )
                %} 
                {% 
                    set breakins = frappe.get_all(
                        "Employee Checkin",
                        filters={
                            "employee": employees[0].employee,
                            "log_type": "IN",
                            "custom_is_break": 1,
                            "time": ["between", [date + " 00:00:00", date + " 23:59:59"]]
                        },
                        fields=["time"],
                        order_by="time ASC", 
                        limit=1 
                    )
                %}  
                {% if checkins and checkins[0] %}
                    {% set checkins_time = checkins[0].time %}
                    {% set checkins_hour = checkins_time.strftime('%H')|int %}
                    {% set checkins_minute = checkins_time.strftime('%M')|int %}
                {% endif %}
                {% if checkouts and checkouts[0] %}
                    {% set checkouts_time = checkouts[0].time %}
                    {% set checkouts_hour = checkouts_time.strftime('%H')|int %}
                    {% set checkouts_minute = checkouts_time.strftime('%M')|int %}
                {% endif %}
                {% if breakouts and breakouts[0] %}
                    {% set breakouts_time = breakouts[0].time %}
                {% endif %}    
                {% if breakins and breakins[0] %}
                    {% set breakins_time = breakins[0].time %}
                {% endif %} 
            {% endif %}
            <tr>
                <td style="font-weight: bold;">{{d}}</td>
                <td>
                    {% if d >= start_day and days_in_month >= d %}
                        {% if checkins and checkins[0] %}
                            {% if  (checkins_hour < 12) or (checkins_hour == 12 and checkins_minute == 0) %}
                                {{ checkins[0].time.strftime('%I:%M %p') }}
                            {% endif %}
                        {% endif %}
                    {% endif %}
                </td>
                <td>
                    {% if d >= start_day and days_in_month >= d %}
                        {% if checkouts and checkouts[0] %}
                            {% if breakouts and breakouts[0] %}
                                {% if checkouts_time < breakouts_time  %}
                                    {% if  (checkouts_hour < 12) or (checkouts_hour == 12 and checkouts_minute == 0) %}
                                        {{ checkouts[0].time.strftime('%I:%M %p') }}
                                    {% endif %}
                                {% else %}
                                    {% if employees[0].custom_category=="Non Acad" %} {{ breakouts[0].time.strftime('%I:%M %p') }} {% endif %}
                                {% endif %}
                            {% else %}   
                                {% if checkins and checkins[0] and date >= target_date %}
                                    {% if employees[0].custom_category=="Non Acad" and (checkins_hour < 12) and (checkins_hour < 13) and ((checkouts_hour > 12 and checkouts_minute > 0) or (checkouts_hour > 13))%}
                                        12:00 PM
                                    {% endif %}
                                {% endif %}
                                {% if  (checkouts_hour < 12) or (checkouts_hour == 12 and checkouts_minute == 0) %}
                                    {{ checkouts[0].time.strftime('%I:%M %p') }}
                                {% endif %}
                            {% endif %}
                        {% else %}
                             {% if breakouts and breakouts[0] %}
                                {% if employees[0].custom_category=="Non Acad" %} {{ breakouts[0].time.strftime('%I:%M %p') }} {% endif %}
                             {% endif %}
                        {% endif %}
                    {% endif %}
                </td>
                <td>
                    {% if d >= start_day and days_in_month >= d %}
                        {% if checkins and checkins[0] %}
                            {% if breakins and breakins[0] %}
                                {% if checkins_time > breakins_time  %}
                                    {% if  (checkins_hour > 12) or (checkins_hour == 12 and checkins_minute > 0) %}
                                        {{ checkins[0].time.strftime('%I:%M %p') }}
                                    {% endif %}
                                {% else %}
                                
                                    {% if employees[0].custom_category=="Non Acad" %} {{ breakins[0].time.strftime('%I:%M %p') }} {% endif %}
                                {% endif %}
                            {% else %}  
                                {% if checkouts and checkouts[0] and date >= target_date %}
                                    {% if employees[0].custom_category=="Non Acad" and (checkins_hour < 12) and (checkins_hour < 13) and ((checkouts_hour > 12 and checkouts_minute > 0) or (checkouts_hour > 13))%}
                                        1:00 PM
                                    {% endif %}
                                {% endif %}
                                {% if  (checkins_hour > 12) or (checkins_hour == 12 and checkins_minute > 0) %}
                                    {{ checkins[0].time.strftime('%I:%M %p') }}
                                {% endif %}
                            {% endif %}
                        {% else %}
                             {% if breakins and breakins[0] %}
                                {% if employees[0].custom_category=="Non Acad" %} {{ breakins[0].time.strftime('%I:%M %p') }} {% endif %}
                             {% endif %}
                        {% endif %}
                    {% endif %}
                </td>
                <td>
                    {% if d >= start_day and days_in_month >= d %}
                        {% if checkouts and checkouts[0] %}
                            {% if  (checkouts_hour > 12) or (checkouts_hour == 12 and checkouts_minute > 0) %}
                                {{ checkouts[0].time.strftime('%I:%M %p') }}
                            {% endif %}
                        {% endif %}
                    {% endif %}
                </td>
                <td></td>
                <td "border: none; width: 0;"></td>
            </tr>

            <tr>
                <td colspan="7" style="position: relative; height: 0;">
                    <span style="position: absolute; left: 100%; bottom: 100%; margin-left: 10px; white-space: nowrap;">
                        
                    {% if d in holiday_days %}
                        Holiday
                    {% endif %}
            {% if checkins|length > 0 and checkouts|length > 0 %}
                {% set ci = checkins[0].custom_remarks %}
                {% set co = checkouts[0].custom_remarks %}
            
                {# Filter out Biometric Device #}
                {% set ci_filtered = "" if ci == "Biometric Device" else ci %}
                {% set co_filtered = "" if co == "Biometric Device" else co %}
            
                {# If both filtered values exist #}
                {% if ci_filtered and co_filtered %}
                    {% if ci_filtered == co_filtered %}
                        {{ ci_filtered }}     {# same value → print once #}
                    {% else %}
                        {{ ci_filtered ~ " / " ~ co_filtered }}
                    {% endif %}
            
                {# Only ci exists #}
                {% elif ci_filtered %}
                    {{ ci_filtered }}
            
                {# Only co exists #}
                {% elif co_filtered %}
                    {{ co_filtered }}
                {% endif %}
            {% endif %}
                                                                                                                                                                                                                                                                                                                                                                                               
                    </span>
                </td>
            </tr>
        {% endfor %}
        <tr style="font-size: 10pt; border-top: double; border-bottom: double;">
            <td colspan="5">TOTAL</td>
            <td style="text-decoration: underline;"></td>
            <td style="text-decoration: underline;"></td>
        </tr>
    </table> 
    <table>
        <tr style="line-height: 2;"><td colspan="7"></td></tr>
        <tr>
            <td colspan="7" style="text-align: justify; border: 1pt solid black; text-indent: 20px; padding: 5px !important; font-style: italic;">I CERTIFY on my honor that the above is a true and correct report of the hours of work perform, record of which was made daily at the time of arrival and departure from office.</td>
        </tr>
        <tr><td colspan="7" style="border-bottom: double; padding-top: 20px !important;">Verified as to the prescribed office hours.</td></tr>
        <tr><td colspan="7" style="padding-top: 30px !important; border-bottom: 2pt solid black;"></td></tr>
        <tr><td colspan="7" style="">In Charge</td></tr>
        <tr><td colspan="7" style=""></td></tr>
        
    </table>
